text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta name="description" content="Dune Line — an overnight train from desert stillness to the neon heart of Lumen City.">
  <title>Dune Line — Cross the sand. Wake to neon.</title>
  <style>
    :root {
      --night: #15101d;
      --night-soft: #211725;
      --night-raised: #291d30;
      --cream: #f5efe5;
      --paper: #fffaf2;
      --ink: #251c27;
      --muted: #72686f;
      --line: #ded4c6;
      --peach: #f1b17e;
      --orange: #df7c55;
      --orange-dark: #ad4e32;
      --mint: #9aefdc;
      --lavender: #b8a0ed;
      --serif: Georgia, "Times New Roman", serif;
      --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
    }

    *, *::before, *::after { box-sizing: border-box; }

    html {
      scroll-behavior: smooth;
      scroll-padding-top: 24px;
    }

    body {
      margin: 0;
      background: var(--cream);
      color: var(--ink);
      font-family: var(--sans);
      font-size: 16px;
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      text-rendering: optimizeLegibility;
    }

    body, button, a { -webkit-tap-highlight-color: transparent; }
    a { color: inherit; text-decoration: none; }
    button { font: inherit; }
    img, svg { display: block; }
    p, h1, h2, h3, blockquote { margin-top: 0; }
    ::selection { background: var(--peach); color: var(--night); }

    .container {
      width: min(1180px, calc(100% - 48px));
      margin-inline: auto;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    .skip-link {
      position: fixed;
      z-index: 100;
      top: 12px;
      left: 12px;
      padding: 10px 16px;
      border-radius: 8px;
      background: var(--paper);
      color: var(--night);
      transform: translateY(-150%);
      transition: transform .2s ease;
    }

    .skip-link:focus { transform: translateY(0); }

    a:focus-visible, button:focus-visible {
      outline: 3px solid var(--mint);
      outline-offset: 4px;
    }

    .site-header {
      position: absolute;
      z-index: 20;
      inset: 0 0 auto;
      color: #fff8ed;
    }

    .nav-wrap {
      position: relative;
      height: 96px;
      display: flex;
      align-items: center;
      border-bottom: 1px solid rgba(255, 255, 255, .1);
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 11px;
      flex-shrink: 0;
      font-size: 14px;
      font-weight: 800;
      letter-spacing: .19em;
      line-height: 1;
    }

    .brand svg { width: 34px; height: 34px; color: var(--peach); }

    .primary-nav {
      display: flex;
      align-items: center;
      gap: 34px;
      margin-left: auto;
      margin-right: 38px;
    }

    .primary-nav a {
      position: relative;
      color: #c9becb;
      font-size: 13px;
      font-weight: 600;
      transition: color .2s ease;
    }

    .primary-nav a:not(.mobile-book)::after {
      content: "";
      position: absolute;
      right: 0;
      bottom: -8px;
      left: 0;
      height: 1px;
      background: var(--peach);
      transform: scaleX(0);
      transform-origin: right;
      transition: transform .25s ease;
    }

    .primary-nav a:hover { color: #fff8ed; }
    .primary-nav a:hover::after { transform: scaleX(1); transform-origin: left; }
    .mobile-book { display: none !important; }

    .nav-cta {
      display: inline-flex;
      align-items: center;
      gap: 18px;
      min-height: 44px;
      padding: 0 18px;
      border: 1px solid rgba(255, 255, 255, .24);
      border-radius: 999px;
      font-size: 12px;
      font-weight: 700;
      transition: background .2s ease, color .2s ease, border-color .2s ease;
    }

    .nav-cta:hover {
      background: #fff7eb;
      border-color: #fff7eb;
      color: var(--night);
    }

    .menu-toggle {
      display: none;
      width: 44px;
      height: 44px;
      margin-left: auto;
      padding: 0;
      border: 1px solid rgba(255, 255, 255, .2);
      border-radius: 50%;
      background: transparent;
      color: white;
      cursor: pointer;
    }

    .menu-toggle span {
      display: block;
      width: 17px;
      height: 1px;
      margin: 5px auto;
      background: currentColor;
      transition: transform .2s ease;
    }

    .menu-toggle[aria-expanded="true"] span:first-child { transform: translateY(3px) rotate(45deg); }
    .menu-toggle[aria-expanded="true"] span:last-child { transform: translateY(-3px) rotate(-45deg); }

    .hero {
      position: relative;
      isolation: isolate;
      overflow: hidden;
      background:
        radial-gradient(circle at 79% 16%, rgba(149, 85, 135, .18), transparent 30%),
        radial-gradient(circle at 10% 70%, rgba(225, 124, 85, .06), transparent 34%),
        var(--night);
      color: #fff8ed;
    }

    .hero::before {
      content: "";
      position: absolute;
      z-index: -1;
      width: 520px;
      height: 520px;
      top: -300px;
      left: -160px;
      border: 1px solid rgba(255, 255, 255, .05);
      border-radius: 50%;
      box-shadow: 0 0 0 90px rgba(255, 255, 255, .015), 0 0 0 180px rgba(255, 255, 255, .01);
    }

    .hero-grid {
      min-height: 760px;
      display: grid;
      grid-template-columns: minmax(0, .92fr) minmax(0, 1.08fr);
      align-items: center;
      gap: 36px;
      padding-top: 126px;
      padding-bottom: 112px;
    }

    .hero-copy { position: relative; z-index: 2; }

    .eyebrow {
      display: flex;
      align-items: center;
      gap: 12px;
      margin-bottom: 22px;
      color: var(--orange-dark);
      font-size: 10px;
      font-weight: 800;
      letter-spacing: .2em;
      line-height: 1.4;
      text-transform: uppercase;
    }

    .eyebrow::before {
      content: "";
      width: 27px;
      height: 1px;
      flex: 0 0 auto;
      background: currentColor;
    }

    .hero .eyebrow { color: var(--peach); }

    .hero-title {
      max-width: 570px;
      margin-bottom: 26px;
      color: #fff8ed;
      font-family: var(--serif);
      font-size: clamp(64px, 6.2vw, 82px);
      font-weight: 400;
      letter-spacing: -.057em;
      line-height: .99;
    }

    .hero-title em {
      color: var(--peach);
      font-weight: 400;
    }

    .hero-summary {
      max-width: 470px;
      margin-bottom: 0;
      color: #c7bcc9;
      font-size: 17px;
      line-height: 1.72;
    }

    .hero-actions {
      display: flex;
      align-items: center;
      flex-wrap: wrap;
      gap: 26px;
      margin-top: 34px;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 22px;
      min-height: 52px;
      padding: 0 24px;
      border: 1px solid transparent;
      border-radius: 999px;
      font-size: 13px;
      font-weight: 750;
      line-height: 1;
      transition: transform .2s ease, background .2s ease, box-shadow .2s ease, border-color .2s ease;
    }

    .btn-light {
      background: #fff7eb;
      color: var(--night);
      box-shadow: 0 10px 30px rgba(0, 0, 0, .16);
    }

    .btn-light:hover {
      background: var(--peach);
      box-shadow: 0 14px 34px rgba(0, 0, 0, .23);
      transform: translateY(-2px);
    }

    .text-link {
      display: inline-flex;
      align-items: center;
      gap: 9px;
      padding-bottom: 3px;
      border-bottom: 1px solid rgba(255, 255, 255, .28);
      color: #e5dbe4;
      font-size: 13px;
      font-weight: 650;
      transition: border-color .2s ease, color .2s ease;
    }

    .text-link:hover { color: var(--peach); border-color: var(--peach); }

    .hero-note {
      display: flex;
      align-items: center;
      gap: 9px;
      margin: 27px 0 0;
      color: #928698;
      font-size: 11px;
      letter-spacing: .035em;
    }

    .hero-note svg { color: var(--peach); }

    .hero-scene {
      position: relative;
      width: 100%;
      border-radius: 31px;
      box-shadow: 0 34px 80px rgba(0, 0, 0, .3);
    }

    .hero-scene > svg {
      width: 100%;
      height: auto;
      border-radius: 31px;
    }

    .scene-coordinate {
      position: absolute;
      top: 22px;
      left: 24px;
      color: rgba(255, 244, 231, .55);
      font-size: 9px;
      font-weight: 700;
      letter-spacing: .16em;
      text-transform: uppercase;
    }

    .scene-status {
      position: absolute;
      right: 20px;
      bottom: 20px;
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 11px 15px;
      border: 1px solid rgba(255, 255, 255, .14);
      border-radius: 999px;
      background: rgba(19, 13, 27, .8);
      box-shadow: 0 8px 24px rgba(0, 0, 0, .18);
      color: #eee3eb;
      font-size: 9px;
      font-weight: 750;
      letter-spacing: .13em;
      text-transform: uppercase;
      backdrop-filter: blur(12px);
    }

    .status-dot {
      display: inline-block;
      width: 7px;
      height: 7px;
      flex: 0 0 auto;
      border-radius: 50%;
      background: var(--mint);
      box-shadow: 0 0 12px rgba(154, 239, 220, .75);
    }

    .star.twinkle { animation: twinkle 3.8s ease-in-out infinite; }
    .star.twinkle.delay { animation-delay: -1.9s; }

    main { background: var(--cream); }

    .route-wrap {
      position: relative;
      z-index: 5;
      margin-top: -52px;
    }

    .route-card {
      display: grid;
      grid-template-columns: 136px minmax(0, 1fr) 48px;
      align-items: center;
      gap: 30px;
      padding: 28px 30px;
      border: 1px solid rgba(92, 67, 61, .1);
      border-radius: 20px;
      background: var(--paper);
      box-shadow: 0 20px 60px rgba(56, 37, 39, .1);
    }

    .route-kicker {
      color: var(--muted);
      font-size: 9px;
      font-weight: 800;
      letter-spacing: .16em;
      line-height: 1.7;
      text-transform: uppercase;
    }

    .route-kicker .service-today {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-bottom: 7px;
      color: var(--orange-dark);
    }

    .route-kicker strong {
      display: block;
      color: var(--ink);
      font-size: 13px;
      letter-spacing: .1em;
    }

    .route-main {
      display: grid;
      grid-template-columns: minmax(0, 1fr) 150px minmax(0, 1fr);
      align-items: center;
      gap: 25px;
    }

    .station {
      display: flex;
      align-items: center;
      gap: 15px;
      min-width: 0;
    }

    .station.arrival {
      justify-content: flex-end;
      text-align: right;
    }

    .station-time {
      color: var(--ink);
      font-family: var(--serif);
      font-size: 32px;
      letter-spacing: -.04em;
      line-height: 1;
      font-variant-numeric: tabular-nums;
    }

    .station strong {
      display: block;
      margin-bottom: 3px;
      font-size: 12px;
      font-weight: 750;
      white-space: nowrap;
    }

    .station small {
      display: block;
      color: var(--muted);
      font-size: 9px;
      white-space: nowrap;
    }

    .route-track { text-align: center; }

    .route-track > span {
      color: var(--muted);
      font-size: 9px;
      font-weight: 700;
      letter-spacing: .06em;
    }

    .route-track small {
      color: #9a8e8b;
      font-size: 8px;
      letter-spacing: .08em;
      text-transform: uppercase;
    }

    .route-line {
      position: relative;
      height: 1px;
      margin: 10px 0 7px;
      background: #d8ccbd;
    }

    .route-line::before, .route-line::after {
      content: "";
      position: absolute;
      top: -3px;
      width: 7px;
      height: 7px;
      border: 1px solid #c5b7a8;
      border-radius: 50%;
      background: var(--paper);
    }

    .route-line::before { left: 0; }
    .route-line::after { right: 0; background: var(--orange); border-color: var(--orange); }

    .route-train {
      position: absolute;
      top: -9px;
      left: 50%;
      padding: 0 7px;
      background: var(--paper);
      color: var(--orange-dark);
      transform: translateX(-50%);
    }

    .route-link {
      display: grid;
      width: 48px;
      height: 48px;
      place-items: center;
      border: 1px solid var(--line);
      border-radius: 50%;
      color: var(--ink);
      font-size: 18px;
      transition: background .2s ease, color .2s ease, transform .2s ease;
    }

    .route-link:hover { background: var(--ink); color: var(--paper); transform: rotate(8deg); }

    .section { padding: 112px 0; }
    .experience { padding-top: 108px; }

    .section-heading {
      display: grid;
      grid-template-columns: minmax(0, 1.25fr) minmax(280px, .75fr);
      align-items: end;
      gap: 70px;
      margin-bottom: 52px;
    }

    .section-heading .eyebrow { margin-bottom: 18px; }

    .section-heading h2 {
      margin-bottom: 0;
      font-family: var(--serif);
      font-size: clamp(42px, 4.2vw, 56px);
      font-weight: 400;
      letter-spacing: -.045em;
      line-height: 1.08;
    }

    .section-lede {
      max-width: 440px;
      margin: 0 0 4px auto;
      color: var(--muted);
      font-size: 15px;
      line-height: 1.8;
    }

    .feature-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 20px;
    }

    .feature-card {
      position: relative;
      min-height: 316px;
      padding: 29px;
      overflow: hidden;
      border: 1px solid var(--line);
      border-radius: 20px;
      background: rgba(255, 250, 242, .58);
      transition: transform .25s ease, background .25s ease, box-shadow .25s ease;
    }

    .feature-card::after {
      content: "";
      position: absolute;
      width: 150px;
      height: 150px;
      right: -85px;
      bottom: -90px;
      border: 1px solid rgba(173, 78, 50, .12);
      border-radius: 50%;
      box-shadow: 0 0 0 26px rgba(173, 78, 50, .025);
    }

    .feature-top {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      margin-bottom: 50px;
    }

    .feature-icon {
      display: grid;
      width: 52px;
      height: 52px;
      place-items: center;
      border-radius: 15px;
      background: #eadcc9;
      color: #844a36;
    }

    .feature-card:nth-child(2) .feature-icon { background: #e3dcf0; color: #5d487e; }
    .feature-card:nth-child(3) .feature-icon { background: #d8e8df; color: #315f56; }

    .feature-number {
      color: #a99b94;
      font-family: var(--serif);
      font-size: 13px;
      font-style: italic;
    }

    .feature-card h3 {
      margin-bottom: 12px;
      font-family: var(--serif);
      font-size: 25px;
      font-weight: 400;
      letter-spacing: -.025em;
      line-height: 1.15;
    }

    .feature-card p {
      max-width: 300px;
      margin-bottom: 0;
      color: var(--muted);
      font-size: 13px;
      line-height: 1.75;
    }

    @media (hover: hover) {
      .feature-card:hover {
        background: var(--paper);
        box-shadow: 0 18px 40px rgba(64, 45, 43, .07);
        transform: translateY(-5px);
      }
    }

    .timetable-section {
      position: relative;
      isolation: isolate;
      overflow: hidden;
      background:
        radial-gradient(circle at 90% 10%, rgba(156, 91, 137, .13), transparent 28%),
        var(--night);
      color: #fff6eb;
    }

    .timetable-section::after {
      content: "";
      position: absolute;
      z-index: -1;
      right: -180px;
      bottom: -260px;
      width: 560px;
      height: 560px;
      border: 1px solid rgba(255, 255, 255, .04);
      border-radius: 50%;
      box-shadow: 0 0 0 70px rgba(255, 255, 255, .012), 0 0 0 140px rgba(255, 255, 255, .008);
    }

    .timetable-section .eyebrow { color: var(--peach); }
    .timetable-section .section-lede { color: #b5a9b8; }

    .board {
      overflow: hidden;
      border: 1px solid rgba(255, 255, 255, .11);
      border-radius: 22px;
      background: rgba(39, 27, 44, .76);
      box-shadow: 0 25px 70px rgba(0, 0, 0, .16);
    }

    .board-top, .board-foot {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
      padding: 19px 25px;
      color: #9f93a5;
      font-size: 9px;
      font-weight: 700;
      letter-spacing: .14em;
      text-transform: uppercase;
    }

    .board-top > span:first-child { display: flex; align-items: center; gap: 10px; color: #d4c8d4; }
    .board-foot { border-top: 1px solid rgba(255, 255, 255, .08); font-weight: 500; letter-spacing: .04em; text-transform: none; }

    .departure-table {
      width: 100%;
      border-collapse: collapse;
      table-layout: fixed;
      font-variant-numeric: tabular-nums;
    }

    .departure-table th {
      padding: 17px 24px;
      border-top: 1px solid rgba(255, 255, 255, .08);
      border-bottom: 1px solid rgba(255, 255, 255, .08);
      color: #887c8e;
      font-size: 9px;
      font-weight: 750;
      letter-spacing: .14em;
      text-align: left;
      text-transform: uppercase;
    }

    .departure-table th:first-child { width: 27%; }
    .departure-table th:nth-child(2), .departure-table th:nth-child(3) { width: 16%; }
    .departure-table th:nth-child(4) { width: 13%; }
    .departure-table th:nth-child(5) { width: 14%; }
    .departure-table th:last-child { width: 14%; }

    .departure-table td {
      padding: 23px 24px;
      border-bottom: 1px solid rgba(255, 255, 255, .075);
      color: #e8dfe8;
      font-size: 13px;
      vertical-align: middle;
      transition: background .2s ease;
    }

    .departure-table tbody tr:last-child td { border-bottom: 0; }
    .departure-table tbody tr:hover td { background: rgba(255, 255, 255, .025); }

    .service-name {
      display: flex;
      align-items: center;
      gap: 12px;
      margin-bottom: 4px;
    }

    .service-code {
      display: inline-flex;
      padding: 4px 7px;
      border: 1px solid rgba(241, 177, 126, .3);
      border-radius: 5px;
      color: var(--peach);
      font-size: 9px;
      font-weight: 800;
      letter-spacing: .09em;
    }

    .service-name strong { font-size: 12px; font-weight: 650; }
    .departure-table td > small { color: #8f8395; font-size: 9px; }

    .table-time {
      display: block;
      margin-bottom: 3px;
      color: #fff8ef;
      font-family: var(--serif);
      font-size: 23px;
      letter-spacing: -.02em;
      line-height: 1.1;
    }

    .table-time sup {
      margin-left: 3px;
      color: var(--peach);
      font-family: var(--sans);
      font-size: 8px;
      letter-spacing: 0;
    }

    .fare-from { color: #918594; font-size: 9px; }
    .fare-from strong { margin-left: 4px; color: #fff6eb; font-family: var(--serif); font-size: 21px; font-weight: 400; }

    .table-arrow {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      width: 42px;
      height: 42px;
      border: 1px solid rgba(255, 255, 255, .16);
      border-radius: 50%;
      color: #f5e9f1;
      font-size: 17px;
      transition: color .2s ease, background .2s ease, border-color .2s ease;
    }

    .table-arrow:hover { background: var(--peach); border-color: var(--peach); color: var(--night); }
    .book-label { display: none; }

    .fares { background: var(--cream); }
    .fare-note {
      margin: 25px 0 0;
      color: var(--muted);
      font-size: 11px;
    }

    .pricing-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      align-items: stretch;
      gap: 20px;
      margin-top: 12px;
    }

    .price-card {
      position: relative;
      display: flex;
      min-height: 530px;
      flex-direction: column;
      padding: 31px;
      border: 1px solid var(--line);
      border-radius: 21px;
      background: var(--paper);
    }

    .price-card.popular {
      border-color: var(--night);
      background:
        radial-gradient(circle at 100% 0, rgba(177, 122, 167, .15), transparent 34%),
        var(--night-soft);
      color: #fff7ed;
      box-shadow: 0 22px 50px rgba(37, 24, 34, .15);
      transform: translateY(-12px);
    }

    .popular-badge {
      position: absolute;
      top: 26px;
      right: 25px;
      padding: 5px 9px;
      border: 1px solid rgba(241, 177, 126, .32);
      border-radius: 999px;
      color: var(--peach);
      font-size: 8px;
      font-weight: 800;
      letter-spacing: .13em;
      text-transform: uppercase;
    }

    .price-card h3 {
      margin-bottom: 10px;
      font-family: var(--serif);
      font-size: 27px;
      font-weight: 400;
      letter-spacing: -.025em;
    }

    .price-description {
      min-height: 48px;
      margin-bottom: 25px;
      color: var(--muted);
      font-size: 12px;
      line-height: 1.65;
    }

    .popular .price-description { color: #b7aaba; }

    .price {
      display: flex;
      align-items: flex-start;
      color: var(--ink);
      line-height: 1;
    }

    .popular .price { color: #fff7ed; }
