    .testimonial::after { width: 340px; height: 340px; right: -130px; bottom: -230px; box-shadow: 0 0 0 55px rgba(59, 31, 40, .025); }

    .quote-mark {
      display: inline-grid;
      width: 48px;
      height: 48px;
      place-items: center;
      margin-bottom: 27px;
      border: 1px solid rgba(43, 27, 36, .25);
      border-radius: 50%;
