    .testimonial blockquote {
      max-width: 920px;
      margin: 0 auto 35px;
      font-family: var(--serif);
      font-size: clamp(34px, 3.7vw, 48px);
      font-weight: 400;
      letter-spacing: -.035em;
      line-height: 1.23;
