    .testimonial-person {
      display: inline-flex;
      align-items: center;
      gap: 13px;
      text-align: left;
    }

    .avatar {
      display: grid;
      width: 42px;
      height: 42px;
      place-items: center;
      border: 1px solid rgba(43, 27, 36, .25);
      border-radius: 50%;
      font-family: var(--serif);
      font-size: 12px;
      font-style: italic;
    }

    .testimonial-person cite {
      display: block;
      margin-bottom: 1px;
      font-size: 11px;
      font-style: normal;
      font-weight: 800;
      letter-spacing: .04em;
    }

    .testimonial-person span:last-child { display: block; color: rgba(43, 27, 36, .65); font-size: 9px; }

    .site-footer {
      background: var(--night);
      color: #fff7ed;
    }

    .footer-main {
      display: grid;
      grid-template-columns: 1.35fr .65fr .65fr;
      gap: 70px;
      padding-top: 84px;
      padding-bottom: 70px;
    }

    .footer-intro .brand { margin-bottom: 32px; }

    .footer-intro h2 {
      margin-bottom: 24px;
      font-family: var(--serif);
      font-size: 46px;
      font-weight: 400;
      letter-spacing: -.04em;
