      font-size: 12px;
      font-weight: 700;
    }

    .footer-cta:hover { border-color: var(--peach); }

    .footer-column h3 {
      margin-bottom: 23px;
      color: #897d8e;
      font-size: 9px;
      font-weight: 800;
      letter-spacing: .17em;
      text-transform: uppercase;
    }

    .footer-column a {
      display: table;
      margin-bottom: 13px;
      color: #c2b6c4;
      font-size: 12px;
      transition: color .2s ease;
    }

    .footer-column a:hover { color: var(--peach); }

    .footer-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 25px;
      padding-top: 23px;
      padding-bottom: 26px;
      border-top: 1px solid rgba(255, 255, 255, .09);
      color: #7f7385;
      font-size: 9px;
      letter-spacing: .035em;
    }

    .back-to-top { color: #b8adbd; }
    .back-to-top:hover { color: var(--peach); }

    @keyframes twinkle {
      0%, 100% { opacity: .35; }
      50% { opacity: 1; }
    }

    @media (max-width: 1100px) {
      .hero-grid { gap: 25px; }
      .hero-title { font-size: clamp(60px, 6.4vw, 72px); }
      .route-card { grid-template-columns: 112px minmax(0, 1fr) 46px; gap: 22px; padding-inline: 24px; }
      .route-main { grid-template-columns: minmax(0, 1fr) 115px minmax(0, 1fr); gap: 18px; }
      .station { gap: 10px; }
      .station-time { font-size: 28px; }
      .station small { display: none; }
      .departure-table th, .departure-table td { padding-inline: 18px; }
      .service-name { gap: 8px; }
    }

    @media (max-width: 900px) {
      .hero-grid {
        grid-template-columns: 1fr;
        gap: 48px;
        padding-top: 150px;
        padding-bottom: 120px;
      }

      .hero-copy { max-width: 690px; }
      .hero-title { max-width: 680px; font-size: 76px; }
      .hero-summary { max-width: 570px; }
      .hero-scene { max-width: 700px; margin-inline: auto; }

      .route-card { grid-template-columns: 1fr auto; }
      .route-kicker { grid-column: 1; grid-row: 1; }
      .route-kicker strong { display: inline; margin-left: 8px; }
      .route-kicker .service-today { display: inline-flex; margin: 0; }
      .route-link { grid-column: 2; grid-row: 1; }
      .route-main { grid-column: 1 / -1; grid-row: 2; grid-template-columns: minmax(0, 1fr) 150px minmax(0, 1fr); }
      .station small { display: block; }

      .section { padding: 90px 0; }
      .experience { padding-top: 90px; }
      .section-heading { grid-template-columns: 1fr; gap: 25px; }
      .section-lede { max-width: 590px; margin-left: 0; }

      .departure-table th:first-child { width: 25%; }
      .service-name strong { display: block; max-width: 90px; line-height: 1.35; }

      .pricing-grid { grid-template-columns: 1fr; max-width: 620px; margin: 0 auto; }
      .price-card { min-height: auto; }
      .price-card.popular { transform: none; }
      .price-description { min-height: 0; }
      .price-card ul { grid-template-columns: 1fr 1fr; }
      .fare-button { margin-top: 5px; }

      .footer-main { grid-template-columns: 1.2fr .8fr .8fr; gap: 35px; }
    }

    @media (max-width: 760px) {
      .container { width: min(100% - 36px, 650px); }
