      .departure-table, .departure-table tbody { display: block; }
      .departure-table thead { display: none; }

      .departure-table tr {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 22px 20px;
        padding: 25px;
        border-bottom: 1px solid rgba(255, 255, 255, .09);
