      .departure-table tbody tr:last-child { border-bottom: 0; }

      .departure-table td {
        display: block;
        padding: 0;
        border: 0;
      }

      .departure-table td::before {
        content: attr(data-label);
        display: block;
        margin-bottom: 8px;
        color: #887c8e;
        font-size: 8px;
        font-weight: 750;
        letter-spacing: .14em;
        text-transform: uppercase;
      }

      .departure-table td:first-child { grid-column: 1 / -1; }
      .departure-table td:last-child { grid-column: 1 / -1; }
      .departure-table td:last-child::before { display: none; }
      .service-name strong { max-width: none; }

      .table-arrow {
        width: 100%;
        height: 45px;
        justify-content: space-between;
        padding: 0 17px;
        border-radius: 10px;
        font-size: 14px;
      }

      .book-label { display: inline; font-size: 11px; font-weight: 700; }
      .board-foot { align-items: flex-start; flex-direction: column; gap: 5px; }

      .footer-main { grid-template-columns: 1fr 1fr; }
      .footer-intro { grid-column: 1 / -1; margin-bottom: 15px; }
    }

    @media (max-width: 560px) {
      .container { width: calc(100% - 32px); }
      .brand { font-size: 12px; gap: 8px; }
      .brand svg { width: 30px; height: 30px; }

      .hero-grid { min-height: 0; padding-top: 122px; padding-bottom: 102px; }
      .hero-title { margin-bottom: 22px; font-size: clamp(45px, 12.5vw, 64px); }
      .hero-summary { font-size: 15px; line-height: 1.7; }
      .hero-actions { align-items: flex-start; flex-direction: column; gap: 21px; margin-top: 29px; }
      .hero-note { align-items: flex-start; font-size: 10px; line-height: 1.6; }
      .hero-scene { border-radius: 22px; }
      .hero-scene > svg { border-radius: 22px; }
      .scene-coordinate { top: 15px; left: 16px; font-size: 7px; }
      .scene-status { right: 12px; bottom: 12px; padding: 8px 11px; font-size: 7px; }

      .route-wrap { margin-top: -40px; }
      .route-card { gap: 23px; padding: 23px 20px; border-radius: 17px; }
      .route-kicker { font-size: 8px; }
      .route-link { width: 42px; height: 42px; }
      .route-main { grid-template-columns: minmax(0, 1fr) 75px minmax(0, 1fr); gap: 10px; }
      .station { align-items: flex-start; flex-direction: column; gap: 8px; }
      .station.arrival { align-items: flex-end; }
      .station-time { font-size: 29px; }
      .station strong { font-size: 10px; white-space: normal; line-height: 1.35; }
      .station small { display: none; }
      .route-track > span { font-size: 8px; }
      .route-track small { font-size: 7px; }

      .section { padding: 74px 0; }
      .experience { padding-top: 76px; }
      .section-heading { margin-bottom: 36px; }
      .section-heading h2 { font-size: 40px; }
      .section-lede { font-size: 14px; }
      .feature-card { padding: 25px; }

      .board-top { align-items: flex-start; flex-direction: column; gap: 7px; padding: 18px 20px; }
      .departure-table tr { padding: 23px 20px; }
      .board-foot { padding: 18px 20px; }

      .price-card { padding: 26px; }
      .price-card ul { grid-template-columns: 1fr; }
      .popular-badge { top: 24px; right: 20px; }

      .testimonial { padding: 78px 0 82px; }
      .testimonial blockquote { font-size: 33px; }

      .footer-main { gap: 45px 25px; padding-top: 65px; padding-bottom: 52px; }
      .footer-intro h2 { font-size: 40px; }
      .footer-bottom { align-items: flex-start; flex-wrap: wrap; }
      .footer-bottom > span:nth-child(2) { width: 100%; order: 3; }
    }

    @media (prefers-reduced-motion: reduce) {
      html { scroll-behavior: auto; }
      *, *::before, *::after {
        animation-duration: .01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: .01ms !important;
      }
    }
  </style>
</head>
